    "question": "How do you make a dashboard people actually use?",
    "is_question": false,
    "form": "Analysis memo: the question, the data, what I did, what I found, what I would do.",
    "object": "A persistent six-leaf paper memo carrying context, project exhibits, findings and next steps.",
    "object_in_pieces": true
  },
  "tests": {
    "swap": {
      "result": "pass",
      "reason": "The memo uses Rafael’s stated working structure and connects his particular sample-tracking, weekly-report and rent-map work."
    },
    "backdrop": {
      "result": "fail",
      "reason": "The leaves mainly rearrange duplicated project summaries beside the document; removing their depth and motion loses presentation rather than an explanation of the work."
    },
    "depth": {
      "result": "pass",
      "reason": "The sequence develops from question and context through work and evidence to synthesis and the next career step."
    },
    "clipart": {
      "result": "pass",
      "reason": "The memo is a confirmed working artifact rather than a stock occupational emblem."
    },
    "honesty": {
      "result": "pass",
      "reason": "The final plan preserves corrected scopes and approximate metrics, omits unsupported claims, and conditions restricted material on clearance."
    },
    "thirty_seconds": {
      "result": "pass",
      "reason": "The opening supplies Rafael’s name, role, dashboard positioning, Rent Map audience and a visible contact shortcut."
    },
    "plain_reader": {
      "result": "pass",
      "reason": "The opening question and description use understandable language without inflated technical claims."
    }
  },
  "copied_example": false,
  "covers": {
    "phone": true,
    "reduced_motion": true,
    "no_3d": true,
    "other_needs": true,
    "look_and_type": true
  },
  "decided_list": true,
  "overstatement": "not_asked",
  "summary": "This is a carefully sourced portfolio structured as Rafael’s analysis memo, with six rearranging paper leaves and thorough accessibility and launch planning. Its greatest weakness is that it promises an answer to the opening question but leaves that synthesis unwritten, while the 3D mostly illustrates the document’s organization."
